import{_ as e,o as t,c as a,a3 as r}from"./chunks/framework.CVt6dz2a.js";const u=JSON.parse('{"title":"EP.24 同一抹橙色的两种身份","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.24-color-management.md","filePath":"comics/EP.24-color-management.md","lastUpdated":1793881879000}'),d={name:"comics/EP.24-color-management.md"};function c(l,o,i,n,s,p){return t(),a("div",null,[...o[0]||(o[0]=[r('<h1 id="ep-24-同一抹橙色的两种身份" tabindex="-1">EP.24 同一抹橙色的两种身份 <a class="header-anchor" href="#ep-24-同一抹橙色的两种身份" aria-label="Permalink to &quot;EP.24 同一抹橙色的两种身份&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../guide/24-color-graphics/basics">24.1 基础入门：色彩空间与线性工作流</a> 延伸阅读：<a href="./../guide/24-color-graphics/advanced">24.2 进阶应用：精度、HDR 与图形学基础原理</a> · <a href="./../guide/24-color-graphics/practice">24.3 实战案例：跨设备一致的色彩校准工作台</a> 动手演示：<a href="./../public/demos/color-graphics/color-space-lab.html">color-space-lab 色彩空间对比台</a> · <a href="./../public/demos/color-graphics/banding-precision-lab.html">banding-precision-lab 色带与精度实验室</a> · <a href="./../public/demos/color-graphics/color-checker.html">color-checker 跨设备色彩校准台</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><table tabindex="0"><thead><tr><th>格</th><th>场景</th></tr></thead><tbody><tr><td>① 困境</td><td>像素酱发现设计稿的橙色 <code>#D67E2C</code> 到了线上变成 <code>#C9772F</code>，标签君在另一台机器上看着更黄，两人当场为&quot;谁的颜色对&quot;吵起来。</td></tr><tr><td>② 揭秘</td><td>码叔画出四步色彩链路：贴图解码 → 线性计算 → 色调映射 → sRGB 编码；颜色不是感觉，是一条可以逐段检查的流水线。</td></tr><tr><td>③ 实证</td><td>摆出 24 色卡与九级灰阶，逐格读取屏幕十六进制：错误链路整块发灰，正确链路与设计值对齐。</td></tr><tr><td>④ 结案</td><td>三条纪律写成色卡：颜色贴图设 sRGB、数据贴图不解码、输出色彩空间固定；参数定版后，颜色才有据可查。</td></tr></tbody></table><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="_1-同一色号-为什么会有两张脸" tabindex="-1">① 同一色号，为什么会有两张脸 <a class="header-anchor" href="#_1-同一色号-为什么会有两张脸" aria-label="Permalink to &quot;① 同一色号，为什么会有两张脸&quot;">​</a></h3><p>设计稿的 <code>#D67E2C</code> 是 sRGB 编码值，进入渲染管线后要先解码成线性值参与光照，最后再编码回 sRGB。任何一段漏掉或重复，屏幕上的十六进制就会变。<strong>同一份贴图、同一组灯光，只要 <code>texture.colorSpace</code> 或 <code>renderer.outputColorSpace</code> 有一个错位，整块颜色就会系统性偏移</strong>——这不是显示器坏了，是链路断了。</p><h3 id="_2-四步链路-进门前脱鞋-出门前穿鞋" tabindex="-1">② 四步链路：进门前脱鞋，出门前穿鞋 <a class="header-anchor" href="#_2-四步链路-进门前脱鞋-出门前穿鞋" aria-label="Permalink to &quot;② 四步链路：进门前脱鞋，出门前穿鞋&quot;">​</a></h3><table tabindex="0"><thead><tr><th>步骤</th><th>做什么</th><th>对应开关</th></tr></thead><tbody><tr><td>① 解码</td><td>颜色贴图 sRGB → 线性</td><td><code>texture.colorSpace = SRGBColorSpace</code></td></tr><tr><td>② 计算</td><td>光照、混合、后处理全在线性空间</td><td>工作色彩空间（默认 Linear-sRGB）</td></tr><tr><td>③ 色调映射</td><td>把 HDR 亮度压回 0~1</td><td><code>renderer.toneMapping</code> / <code>toneMappingExposure</code></td></tr><tr><td>④ 编码</td><td>线性 → sRGB 写给屏幕</td><td><code>renderer.outputColorSpace</code></td></tr></tbody></table><p>口诀是&quot;<strong>进门前脱鞋，出门前穿鞋</strong>&quot;：贴图进门时脱掉 sRGB，屏幕出门前再穿上。中间所有房间都只认线性值。</p><h3 id="_3-色卡与取色-把-我觉得-变成数字" tabindex="-1">③ 色卡与取色：把&quot;我觉得&quot;变成数字 <a class="header-anchor" href="#_3-色卡与取色-把-我觉得-变成数字" aria-label="Permalink to &quot;③ 色卡与取色：把&quot;我觉得&quot;变成数字&quot;">​</a></h3><p>24 色卡覆盖肤色、天空、植物、高饱和色与中性色，九级灰阶负责暴露对比度与黑位问题。排查时不看感觉，按顺序做：同一环境截图 → 取色记录十六进制 → 逐环节核对贴图、输出、色调映射、后处理 → 把确认过的参数写成一份 <code>COLOR_CONFIG</code> 定版。<strong>能复现的差异才是可修复的差异</strong>。</p><h3 id="_4-三条纪律与一份配置" tabindex="-1">④ 三条纪律与一份配置 <a class="header-anchor" href="#_4-三条纪律与一份配置" aria-label="Permalink to &quot;④ 三条纪律与一份配置&quot;">​</a></h3><ul><li>颜色贴图必须显式 <code>SRGBColorSpace</code>，数据贴图（法线 / 粗糙度 / AO）必须 <code>NoColorSpace</code>；</li><li><code>renderer.outputColorSpace</code> 固定 sRGB，除调试外不许改成 Linear；</li><li>色调映射与曝光从同一份配置读取，后处理链最多做一次 tone mapping。</li></ul><p>把 <code>outputColorSpace</code>、<code>toneMapping</code>、<code>toneMappingExposure</code>、贴图色彩空间、HDR 缓冲类型收进一个带版本号的常量对象，代码评审时颜色变化就有据可查。</p><h2 id="坑点清单-faq" tabindex="-1">坑点清单（FAQ） <a class="header-anchor" href="#坑点清单-faq" aria-label="Permalink to &quot;坑点清单（FAQ）&quot;">​</a></h2><ul><li><strong>Q：颜色整体发灰、发淡？</strong> 颜色贴图被当成线性数据了。设 <code>SRGBColorSpace</code>，并记得 <code>needsUpdate = true</code>。</li><li><strong>Q：画面整体偏暗、饱和色发闷？</strong> 输出漏了 sRGB 编码。<code>outputColorSpace</code> 改回 <code>SRGBColorSpace</code>，不要用曝光硬补。</li><li><strong>Q：法线贴图让光照发脏？</strong> 数据贴图被 sRGB 解码了。法线、粗糙度、AO、ORM 一律 <code>NoColorSpace</code>。</li><li><strong>Q：暗部渐变出现色带？</strong> 8 位缓冲精度不够。先加抖动，再考虑 HalfFloat RenderTarget；抖动必须在量化之前。</li><li><strong>Q：用了后处理颜色变淡？</strong> 可能做了两次色调映射。让 <code>OutputPass</code> 统一负责压缩与编码。</li></ul><h2 id="自测-quiz" tabindex="-1">自测（Quiz） <a class="header-anchor" href="#自测-quiz" aria-label="Permalink to &quot;自测（Quiz）&quot;">​</a></h2><ol><li>颜色贴图与法线贴图分别应该设置什么 <code>colorSpace</code>？为什么不能一视同仁？</li><li>完整的四步色彩链路是什么？<code>toneMapping</code> 和 <code>outputColorSpace</code> 各自位于哪一步？</li><li>团队里出现&quot;设计稿与线上颜色不一致&quot;，你会按什么顺序排查？最终如何避免再次发生？</li></ol><details><summary>答案</summary><ol><li>颜色贴图设 <code>THREE.SRGBColorSpace</code>，因为它存的是给人看的 sRGB 颜色，采样时要解码成线性；法线贴图设 <code>THREE.NoColorSpace</code>（或 <code>LinearSRGBColorSpace</code>），因为它存的是方向分量，不是颜色，被解码会扭弯法线、导致光照发脏。口诀：能当颜色画出来的图用 sRGB，只能当数字读的图用 NoColorSpace。</li><li>四步是：① 贴图解码（sRGB → 线性）；② 线性空间计算（光照、混合、后处理）；③ 色调映射（在仍为线性的 HDR 值上压缩）；④ 输出编码（线性 → sRGB）。<code>toneMapping</code> 属于第 ③ 步，<code>outputColorSpace</code> 属于第 ④ 步。</li><li>排查顺序：统一截图环境 → 取色记录十六进制 → 逐环节核对贴图 colorSpace、输出 colorSpace、toneMapping / exposure、后处理是否重复映射 → 把确认过的参数写成 <code>COLOR_CONFIG</code> 定版 → 每次发布保留色卡基线截图做回归。避免再次发生靠的是&quot;配置收敛 + 视觉回归&quot;，而不是反复口头对色。</li></ol></details>',20)])])}const g=e(d,[["render",c]]);export{u as __pageData,g as default};
